-- Invalidate signed action snapshots on automation/audience mutations, including cascades.
-- Cleanup also invalidates pending actions conservatively; clients must begin again.
CREATE INDEX IF NOT EXISTS entry_shares_automation_recipient ON entry_shares(recipient_id,allow_automation,revoked_at,entry_id);
CREATE TRIGGER grant_assignment_delete AFTER DELETE ON access_grants BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE owner_id=OLD.owner_id; END;
CREATE TRIGGER audience_entry_tokens_insert AFTER INSERT ON entry_tokens BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entry_id=NEW.entry_id; END;
CREATE TRIGGER audience_entry_tokens_update AFTER UPDATE ON entry_tokens BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entry_id=NEW.entry_id; END;
CREATE TRIGGER audience_entry_tokens_delete AFTER DELETE ON entry_tokens BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entry_id=OLD.entry_id; END;
CREATE TRIGGER audience_machine_profiles_insert AFTER INSERT ON machine_profiles BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entry_id IN (SELECT entry_id FROM entries WHERE owner_id=NEW.creator_id UNION SELECT r.entry_id FROM entry_readers r WHERE r.recipient_id=NEW.creator_id AND r.allow_automation=1); END;
CREATE TRIGGER audience_machine_profiles_update AFTER UPDATE ON machine_profiles BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entry_id IN (SELECT entry_id FROM entries WHERE owner_id=NEW.creator_id UNION SELECT r.entry_id FROM entry_readers r WHERE r.recipient_id=NEW.creator_id AND r.allow_automation=1); END;
CREATE TRIGGER audience_machine_profiles_delete AFTER DELETE ON machine_profiles BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entry_id IN (SELECT entry_id FROM entries WHERE owner_id=OLD.creator_id UNION SELECT r.entry_id FROM entry_readers r WHERE r.recipient_id=OLD.creator_id AND r.allow_automation=1); END;
CREATE TRIGGER audience_machine_profile_entries_insert AFTER INSERT ON machine_profile_entries BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entry_id IN (SELECT entry_id FROM entries WHERE owner_id=(SELECT creator_id FROM machine_profiles WHERE profile_id=NEW.profile_id) UNION SELECT r.entry_id FROM entry_readers r WHERE r.recipient_id=(SELECT creator_id FROM machine_profiles WHERE profile_id=NEW.profile_id) AND r.allow_automation=1); END;
CREATE TRIGGER audience_machine_profile_entries_update AFTER UPDATE ON machine_profile_entries BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entry_id IN (SELECT entry_id FROM entries WHERE owner_id=(SELECT creator_id FROM machine_profiles WHERE profile_id=NEW.profile_id) UNION SELECT r.entry_id FROM entry_readers r WHERE r.recipient_id=(SELECT creator_id FROM machine_profiles WHERE profile_id=NEW.profile_id) AND r.allow_automation=1); END;
CREATE TRIGGER audience_machine_profile_entries_delete AFTER DELETE ON machine_profile_entries BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entry_id IN (SELECT entry_id FROM entries WHERE owner_id=(SELECT creator_id FROM machine_profiles WHERE profile_id=OLD.profile_id) UNION SELECT r.entry_id FROM entry_readers r WHERE r.recipient_id=(SELECT creator_id FROM machine_profiles WHERE profile_id=OLD.profile_id) AND r.allow_automation=1); END;
CREATE TRIGGER audience_machine_tokens_insert AFTER INSERT ON machine_tokens BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entry_id IN (SELECT entry_id FROM entries WHERE owner_id=(SELECT creator_id FROM machine_profiles WHERE profile_id=NEW.profile_id) UNION SELECT r.entry_id FROM entry_readers r WHERE r.recipient_id=(SELECT creator_id FROM machine_profiles WHERE profile_id=NEW.profile_id) AND r.allow_automation=1); END;
CREATE TRIGGER audience_machine_tokens_update AFTER UPDATE ON machine_tokens BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entry_id IN (SELECT entry_id FROM entries WHERE owner_id=(SELECT creator_id FROM machine_profiles WHERE profile_id=NEW.profile_id) UNION SELECT r.entry_id FROM entry_readers r WHERE r.recipient_id=(SELECT creator_id FROM machine_profiles WHERE profile_id=NEW.profile_id) AND r.allow_automation=1); END;
CREATE TRIGGER audience_machine_tokens_delete AFTER DELETE ON machine_tokens BEGIN UPDATE entries SET mutation_revision=mutation_revision+1 WHERE entry_id IN (SELECT entry_id FROM entries WHERE owner_id=(SELECT creator_id FROM machine_profiles WHERE profile_id=OLD.profile_id) UNION SELECT r.entry_id FROM entry_readers r WHERE r.recipient_id=(SELECT creator_id FROM machine_profiles WHERE profile_id=OLD.profile_id) AND r.allow_automation=1); END;
